/** 生成一个会话内唯一的 id */
export function createId(prefix: string): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/** 生成随机种子 (服务端接受非负整数; -1 表示由服务端随机) */
export function randomSeed(): number {
  return Math.floor(Math.random() * 0xffffffff);
}

/** 解析一条对话在场景卡中的定位键 (与后端 `say_hash` 输入一致) */
export function dialogueKey(line: SayLine): string {
  return `${line.speaker ?? ''}\u001f${line.text.trim()}`;
}

/** 构造默认参数 */
export function defaultParams(character: Character | null, text: string): VoiceParams {
  return {
    characterId: character?.id ?? null,
    referenceHash: character?.references[0]?.hash ?? null,
    language: character?.language ?? 'auto',
    text,
    seed: randomSeed(),
    temperature: PARAM_TICKS.temperature.default,
    speedFactor: PARAM_TICKS.speedFactor.default,
    topK: PARAM_TICKS.topK.default,
    topP: PARAM_TICKS.topP.default,
    repetitionPenalty: PARAM_TICKS.repetitionPenalty.default,
    sampleSteps: GENERATE_SAMPLE_STEPS,
    textSplitMethod: 'cut5',
  };
}

/** 任务的完整参数缓存键 (用于判断"参数是否改动" -> 是否属于新配置) */
export function paramsKey(params: VoiceParams): string {
  return JSON.stringify([
    params.characterId,
    params.referenceHash,
    params.language,
    params.text.trim(),
    params.seed,
    params.temperature,
    params.speedFactor,
    params.topK,
    params.topP,
    params.repetitionPenalty,
    params.sampleSteps,
    params.textSplitMethod,
  ]);
}
